import os
import requests


class Auth0TokenRefreshError(Exception):
    pass


def refresh_auth0_session(refresh_token: str) -> dict:
    domain = os.environ["AUTH0_DOMAIN"].strip()
    client_id = os.environ["AUTH0_CLIENT_ID"].strip()
    client_secret = os.environ["AUTH0_CLIENT_SECRET"].strip()

    url = f"https://{domain}/oauth/token"
    payload = {
        "grant_type": "refresh_token",
        "client_id": client_id,
        "client_secret": client_secret,
        "refresh_token": refresh_token,
    }
    headers = {"Content-Type": "application/json"}

    response = requests.post(url, json=payload, headers=headers, timeout=30)

    if not response.ok:
        try:
            error_body = response.json()
        except ValueError:
            error_body = {"error": "invalid_response", "error_description": response.text}
        raise Auth0TokenRefreshError(
            f"Auth0 token refresh failed: {error_body.get('error')} - {error_body.get('error_description')}"
        )

    data = response.json()

    return {
        "access_token": data.get("access_token"),
        "id_token": data.get("id_token"),
        "refresh_token": data.get("refresh_token", refresh_token),
        "token_type": data.get("token_type"),
        "expires_in": data.get("expires_in"),
        "scope": data.get("scope"),
    }
